INSERT INTO hypothesis_revisions(hypothesis_id,revision,content,science_revision,author_user,via_channel,created_at) SELECT id,1,CASE WHEN number=11 THEN jsonb_build_object('schema_version','0.2','track','alpha','title',title,'question','Legacy authored question') ELSE '{"schema_version":"0.2","track":"alpha","title":"Fixture hypothesis","question":"Does this fixture improve retrieval?","rationale":"Compare the authored fixture observations.","intervention":"Evaluate the fixture retrieval change.","plan":{"selection_splits":["dev"],"confirmation_splits":["test"],"primary_metric":"ndcg","required_slices":[],"success_criteria":"Primary metric improves.","falsification_criteria":"Primary metric does not improve.","regression_gates":[],"compute_budget":{"cpu_hours_max":2}}}'::jsonb || jsonb_build_object('title',title,'project_fields',jsonb_build_object('raw',jsonb_build_array(1,true,null,'é'))) END,7,created_by_user,'historical-channel','2001-01-01T00:00:00Z' FROM hypotheses WHERE project_id='00000000-0000-0000-0000-000000000010';
