INSERT INTO hypotheses(id,project_id,number,track_id,title,created_by_user,created_at,updated_at,state,approved_revision,approved_at) SELECT ('00000000-0000-0000-0000-'||lpad((100+i)::text,12,'0'))::uuid,'00000000-0000-0000-0000-000000000010',i,'00000000-0000-0000-0000-000000000030','Recovery '||i,'00000000-0000-0000-0000-000000000002','2001-01-01T00:00:00Z','2001-01-01T00:00:00Z','queued',1,'2001-01-01T00:00:00Z' FROM generate_series(13,18)i;
INSERT INTO hypothesis_revisions(hypothesis_id,revision,content,science_revision,author_user,via_channel,created_at) SELECT id,1,CASE number WHEN 13 THEN 'null'::jsonb WHEN 14 THEN '[]'::jsonb WHEN 15 THEN '42'::jsonb ELSE '{"schema_version":"0.2","track":"alpha","title":"Fixture hypothesis","question":"Does this fixture improve retrieval?","rationale":"Compare the authored fixture observations.","intervention":"Evaluate the fixture retrieval change.","plan":{"selection_splits":["dev"],"confirmation_splits":["test"],"primary_metric":"ndcg","required_slices":[],"success_criteria":"Primary metric improves.","falsification_criteria":"Primary metric does not improve.","regression_gates":[],"compute_budget":{"cpu_hours_max":2}}}'::jsonb || jsonb_build_object('title',title,'project_fields',jsonb_build_object('wide', ('1'||repeat('0',500))::numeric,'float',1e-7,'unicode','é')) END,7,created_by_user,'api','2001-01-01T00:00:00Z' FROM hypotheses WHERE number BETWEEN 13 AND 18;
